-- Resources content for Sourcework: two guides from 20261103120000 re-issued with corrected
-- wording after review (CLAUDE.md, "Resources stay in step with the code"). Content only; no
-- schema; no new release note, since 20261103120000's note already covers these guides.
--
-- Synthesis: the tab's badge and the "Update synthesis" label count findings accepted after
-- the *version shown*, and tracking or dismissing a pattern saves a person-authored version
-- (getSynthesisStanding() in lib/sourcework/synthesis-queries.ts), so "since the last run" was
-- wrong. Outline: generateOutline() passes at most MAX_OUTLINE_EXCERPTS (150) excerpts, and
-- outlineReadiness() warns only when the project has no accepted excerpt, not whenever
-- suggestions are waiting (lib/sourcework/outline-readiness.ts).
--
-- A separate file rather than an edit, because 20261103120000 was already applied to both
-- projects when the review landed. The prefix continues the sequence; see that file's header.

select private.rc_release_guide(
  p_slug => 'sourcework-synthesis',
  p_tool_key => 'transcription',
  p_title => 'Synthesis',
  p_summary => 'Read what a project''s accepted findings establish for each research question, hear the evidence, and decide what to do with the patterns that emerge.',
  p_screen_keys => array['sourcework.synthesis'],
  p_sort_order => 20,
  p_version_note => 'The badge counts from the version shown, which a tracked or dismissed pattern also saves',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis reads every finding you have accepted in a project and says what they establish about each of your research questions. It is a reading aid: nothing on this tab is evidence, and every statement opens onto the findings behind it. The tab appears once the project has an accepted finding, and its badge counts the findings accepted since the version it shows was saved."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The top of the tab"}]},{"type":"paragraph","content":[{"type":"text","text":"The header says which version you are reading, when it was written and how many findings and sources it reads. "},{"type":"text","text":"Synthesize","marks":[{"type":"bold"}]},{"type":"text","text":" writes the first version; afterwards the button reads "},{"type":"text","text":"Update synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" when findings have been accepted since the version shown, or "},{"type":"text","text":"Synthesize again","marks":[{"type":"bold"}]},{"type":"text","text":". The version menu lists every earlier one; reading an old version is read-only. When a version is not the first, a line under the header says what changed since the previous run: new statements, removed ones, and statements whose certainty moved."}]},{"type":"paragraph","content":[{"type":"text","text":"Under it, a summary shows the whole answer at once: how many statements are established, contested and uncertain, and how many tensions, open points and patterns there are. A count in red means statements that no longer have an accepted finding behind them. The chips under the summary show only statements of one certainty."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reading a statement"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each statement carries a certainty. Five dots show how many different sources it rests on, and "},{"type":"text","text":"One source's account","marks":[{"type":"bold"}]},{"type":"text","text":" marks a statement that rests on a single source."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Evidence","marks":[{"type":"bold"}]},{"type":"text","text":" on a statement to open the findings behind it beside the synthesis, or in a sheet on a phone. Play at a time plays that finding in place, and "},{"type":"text","text":"Open in source","marks":[{"type":"bold"}]},{"type":"text","text":" goes to the passage in the full recording or page."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Sections","marks":[{"type":"bold"}]},{"type":"text","text":" list moves between questions, patterns, conflicts and the moments worth hearing."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Patterns, and what is still open"}]},{"type":"paragraph","content":[{"type":"text","text":"Patterns across sources are things several people described separately that no question asked about. A pattern marked "},{"type":"text","text":"Passages only","marks":[{"type":"bold"}]},{"type":"text","text":" rests on moments the model found in the recordings, not on an accepted finding, so treat it as less firm. A pattern marked "},{"type":"text","text":"New","marks":[{"type":"bold"}]},{"type":"text","text":" was not in the previous run."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track as a research question","marks":[{"type":"bold"}]},{"type":"text","text":" adds a question on the Setup tab, so the next Analyze listens for it. The pattern then reads "},{"type":"text","text":"Tracking","marks":[{"type":"bold"}]},{"type":"text","text":" and cannot be added twice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dismiss","marks":[{"type":"bold"}]},{"type":"text","text":" hides a pattern. Dismissed patterns are listed under the patterns, with "},{"type":"text","text":"Restore","marks":[{"type":"bold"}]},{"type":"text","text":", and a new run does not offer them again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each open point has the same "},{"type":"text","text":"Track as a question","marks":[{"type":"bold"}]},{"type":"text","text":" action."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Choices you make here are saved as a new version marked as edited by a person, and a later run keeps them as they are. Because that is a version too, the badge and the Update synthesis label count findings accepted after it, not after the last model run."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-outline',
  p_tool_key => 'transcription',
  p_title => 'Outline a piece',
  p_summary => 'Plan a piece as beats before any narration is written, then write the outline out in place.',
  p_screen_keys => array['sourcework.piece'],
  p_sort_order => 22,
  p_version_note => 'When the readiness warning shows, and the 150-excerpt limit',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline plans a piece before any narration is written. It is a list of beats, each saying what that part of the story has to do, with your excerpts placed where they belong. You edit the outline, then write it out. Nothing is written for you until you ask."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outline an empty piece"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a new piece and choose "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":" on the "},{"type":"text","text":"Start your piece","marks":[{"type":"bold"}]},{"type":"text","text":" panel. The card says which format it is writing to; change it with "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece, where the format's guide is. Add a direction if you have one, and choose "},{"type":"text","text":"Outline the piece","marks":[{"type":"bold"}]},{"type":"text","text":". It can take a few minutes, because the model may check the transcripts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It works from the findings you have accepted, the project's synthesis if there is one, and the project's excerpts, up to the 150 newest. The first beat is the angle: the point of the piece in a sentence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the project has no accepted excerpts yet, the panel says so and links to the Review tab, since an outline can only place excerpts you have accepted and this one would be beats with no tape. The message also says how many suggestions are still waiting for review. Once the project has an excerpt, no warning is shown, even with suggestions waiting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The result is an ordinary version. Use History to go back, and edit it like any other piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Read a beat"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A beat takes no time, so the length at the top counts only narration and excerpts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What carries it","marks":[{"type":"bold"}]},{"type":"text","text":" opens the findings the beat rests on, with a link to listen where each was said. A finding you have since rejected is counted as no longer accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark to check","marks":[{"type":"bold"}]},{"type":"text","text":" flags a beat whose figure, name or attribution rests on one source or isn't settled. When the outline is written out, that sentence gets a bracketed check note instead of being stated as fact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tape","marks":[{"type":"bold"}]},{"type":"text","text":" links to a stretch of a recording the outline thought worth your attention that is not an excerpt yet. Open it, and make an excerpt if you want it in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change the outline"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit a beat's text directly. Use the + between blocks to add a narration block, an outline beat or an excerpt, and the ⋮ menu to move or remove one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The assistant can add and change beats too. Every change it makes is a version you can undo."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Write from outline"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece with beats shows "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":". It writes each beat out as narration, in the same place, following the Writing guide editors maintain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your excerpts, their trims, and anything you already wrote stay exactly as they are. The model cannot reorder the piece, add a clip or drop one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A beat the model leaves unwritten stays in the outline, and the page says how many. Undo returns you to the outline."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline and a draft are suggestions. Check every name, figure and attribution before you air anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A project with more than 150 excerpts has its oldest ones left out of the outline; an excerpt the outline did not place can still be added by hand."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview text and your findings are sent to an outside service, as for transcription."}]}]}]}]}$body$
);

